import { bookingInProgressGuard } from './booking-guard';
import { Checkout } from './checkout/checkout';
import { MovieList } from './movie-list/movie-list';
import { ScreenPlaceholder } from './screen-placeholder';
import { SeatSelection } from './seat-selection/seat-selection';
import { Summary } from './summary/summary';

export const appRoutes: Route[] = [
  { path: '', component: MovieList },
  { path: 'screenings/:id/seats', component: SeatSelection },
  { path: 'screenings/:id/summary', component: Summary, canActivate: [bookingInProgressGuard] },
  { path: 'screenings/:id/checkout', component: Checkout, canActivate: [bookingInProgressGuard] },
  { path: 'confirmation', component: ScreenPlaceholder },
  { path: '**', redirectTo: '' },
];
import { ApplicationConfig, provideBrowserGlobalErrorListeners } from '@angular/core';
import { provideHttpClient } from '@angular/common/http';
import { provideNativeDateAdapter } from '@angular/material/core';
import { provideRouter } from '@angular/router';
import { appRoutes } from './app.routes';

export const appConfig: ApplicationConfig = {
  providers: [
    provideBrowserGlobalErrorListeners(),
    provideHttpClient(),
    provideRouter(appRoutes),
    provideNativeDateAdapter(),
  ],
};
import { Injectable } from '@angular/core';

/** A selected seat, or a couch covering two adjacent columns of row 15. */
export interface BookedSeat {
  kind: 'seat' | 'couch';
  row: number;
  /** The column of a seat, or the left column of a couch. */
  column: number;
  /** Equal to `column` for a seat, `column + 1` for a couch. */
  columnEnd: number;
}

/** The values typed into the checkout form, kept as they are typed (section 7.1). */
export interface CheckoutValues {
  firstName: string;
  lastName: string;
  email: string;
  confirmEmail: string;
  phone: string;
  termsAccepted: boolean;
}

/** The booking: one screening, the seats chosen for it and, once paid, the customer's email. */
export interface Booking {
  screeningId: number;
  seats: BookedSeat[];
  /** The checkout form values. Absent until the form is first changed. */
  checkout?: CheckoutValues;
  /** The customer's email address once the booking is paid; absent while it is in progress. */
  paidEmail?: string;
}

const STORAGE_KEY = 'cinescope.booking';

/** Orders seats by row, then by column. */
export function sortSeats(seats: readonly BookedSeat[]): BookedSeat[] {
  return [...seats].sort((a, b) => a.row - b.row || a.column - b.column);
}

/** Whether two entries are the same seat or couch. */
export function isSameSeat(a: BookedSeat, b: BookedSeat): boolean {
  return a.row === b.row && a.column === b.column;
}

/**
 * Keeps the booking in `sessionStorage`, so it survives a page reload. The storage is read on
 * every call; nothing is cached, so the guards and the screens always see the same booking.
 */
@Injectable({ providedIn: 'root' })
export class BookingService {
  /** The booking in progress, or null when there is none. */
  current(): Booking | null {
    const raw = sessionStorage.getItem(STORAGE_KEY);
    if (raw === null) {
      return null;
    }
    try {
      const value = JSON.parse(raw) as Partial<Booking> | null;
      if (value && Number.isInteger(value.screeningId) && Array.isArray(value.seats)) {
        return {
          screeningId: value.screeningId as number,
          seats: value.seats,
          checkout: value.checkout,
          paidEmail: value.paidEmail,
        };
      }
    } catch {
      // A corrupted entry is treated as no booking.
    }
    return null;
  }

  /** Replaces the booking in progress. */
  save(booking: Booking): void {
    sessionStorage.setItem(STORAGE_KEY, JSON.stringify(booking));
  }

  /**
   * Replaces the seats of the booking for a screening and keeps the rest of it (the checkout
   * values). The seat map and the summary both change the seats of the booking in progress.
   */
  saveSeats(screeningId: number, seats: BookedSeat[]): void {
    const current = this.current();
    this.save({ ...(current?.screeningId === screeningId ? current : {}), screeningId, seats });
  }

  /** Keeps the checkout form values in the booking in progress. */
  saveCheckout(checkout: CheckoutValues): void {
    const current = this.current();
    if (current) {
      this.save({ ...current, checkout });
    }
  }

  /** Marks the booking in progress as paid, with the customer's email address. */
  markPaid(email: string): void {
    const current = this.current();
    if (current) {
      this.save({ ...current, paidEmail: email });
    }
  }

  /**
   * The booking for a screening: the booking in progress when it belongs to that screening,
   * otherwise a new, empty booking that replaces the previous one.
   */
  openFor(screeningId: number): Booking {
    const current = this.current();
    if (current?.screeningId === screeningId) {
      return current;
    }
    const booking: Booking = { screeningId, seats: [] };
    this.save(booking);
    return booking;
  }

  /** Removes the booking. */
  clear(): void {
    sessionStorage.removeItem(STORAGE_KEY);
  }
}
import { inject } from '@angular/core';
import { CanActivateFn, Router } from '@angular/router';
import { BookingService } from './booking';

/**
 * Lets the customer enter the summary or the checkout of the booking in progress: the booking
 * must be unpaid, belong to the screening in the URL and hold at least one seat. Otherwise the
 * customer is redirected to `/`.
 */
export const bookingInProgressGuard: CanActivateFn = (route) => {
  const booking = inject(BookingService).current();
  const screeningId = Number(route.paramMap.get('id'));
  const allowed =
    booking !== null &&
    booking.screeningId === screeningId &&
    booking.seats.length > 0 &&
    booking.paidEmail === undefined;
  return allowed ? true : inject(Router).createUrlTree(['/']);
};
import { ActivatedRouteSnapshot, RouterStateSnapshot, convertToParamMap, provideRouter } from '@angular/router';
import { TestBed } from '@angular/core/testing';
import { BookingService } from './booking';
import { bookingInProgressGuard } from './booking-guard';

describe('bookingInProgressGuard', () => {
  const seat = { kind: 'seat' as const, row: 2, column: 6, columnEnd: 6 };

  /** Runs the guard for the screen `/screenings/:id/...`; returns true or the redirect as a string. */
  const run = (id: string): true | string =>
    TestBed.runInInjectionContext(() => {
      const route = { paramMap: convertToParamMap({ id }) } as unknown as ActivatedRouteSnapshot;
      const result = bookingInProgressGuard(route, {} as RouterStateSnapshot);
      return result === true ? true : String(result);
    });

  beforeEach(() => {
    sessionStorage.clear();
    TestBed.configureTestingModule({ providers: [provideRouter([])] });
  });

  it('lets the customer in when the booking holds seats for the screening', () => {
    TestBed.inject(BookingService).save({ screeningId: 1, seats: [seat] });
    expect(run('1')).toBe(true);
  });

  it('redirects to the movie list without a booking', () => {
    expect(run('1')).toBe('/');
  });

  it('redirects to the movie list when the booking belongs to another screening', () => {
    TestBed.inject(BookingService).save({ screeningId: 2, seats: [seat] });
    expect(run('1')).toBe('/');
  });

  it('redirects to the movie list when the booking holds no seats', () => {
    TestBed.inject(BookingService).save({ screeningId: 1, seats: [] });
    expect(run('1')).toBe('/');
  });

  it('redirects to the movie list when the booking is already paid', () => {
    TestBed.inject(BookingService).save({ screeningId: 1, seats: [seat], paidEmail: 'anna@example.com' });
    expect(run('1')).toBe('/');
  });
});

import { Component, computed, inject, signal } from '@angular/core';
import { MatButton } from '@angular/material/button';
import { MatCheckbox } from '@angular/material/checkbox';
import { MatFormField, MatLabel } from '@angular/material/form-field';
import { MatInput } from '@angular/material/input';
